import{_ as p,a0 as d,w as s,s as l,I as o,x as t,a1 as a,A as n,ao as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"5 个提高效率的 GNOME 快捷键 | LCTT x X-CMD","titleTemplate":false,"description":"5 个提高效率的 GNOME 快捷键 | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"5 个提高效率的 GNOME 快捷键 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"5 个提高效率的 GNOME 快捷键 | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190527 5 GNOME keyboard shortcuts to be more productive","title":"5 个提高效率的 GNOME 快捷键","tag":"201906","desc":""},"relativePath":"201906/20190527 5 GNOME keyboard shortcuts to be more productive.md","filePath":"[post].md"}'),u={name:"201906/20190527 5 GNOME keyboard shortcuts to be more productive.md"};function m(f,e,g,h,E,b){const r=d("Link");return s(),l("div",null,[e[25]||(e[25]=o("h1",{id:"_5-个提高效率的-gnome-快捷键",tabindex:"-1"},[t("5 个提高效率的 GNOME 快捷键 "),o("a",{class:"header-anchor",href:"#_5-个提高效率的-gnome-快捷键","aria-label":"Permalink to “5 个提高效率的 GNOME 快捷键”"},"​")],-1)),e[26]||(e[26]=o("p",null,[o("img",{src:"https://fedoramagazine.org/wp-content/uploads/2019/05/5-gnome-keycombos-816x345.jpg",alt:""})],-1)),o("p",null,[e[1]||(e[1]=t("对于某些人来说，使用 GNOME Shell 作为传统的桌面管理器可能会感觉沮丧，因为它通常需要更多的鼠标操作。事实上，GNOME Shell 也是一个专为键盘操作而设计的",-1)),a(r,{href:"https://fedoramagazine.org/gnome-3-32-released-coming-to-fedora-30/"},{default:n(()=>[...e[0]||(e[0]=[t("桌面管理器",-1)])]),_:1}),e[2]||(e[2]=t("。通过这五种使用键盘而不是鼠标的方法，了解如何使用 GNOME Shell 提高效率。",-1))]),e[27]||(e[27]=i('<h3 id="gnome-活动概述" tabindex="-1">GNOME 活动概述 <a class="header-anchor" href="#gnome-活动概述" aria-label="Permalink to “GNOME 活动概述”">​</a></h3><p>可以使用键盘上的 <code>Super</code> 键轻松打开活动概述。（<code>Super</code> 键通常有一个标识——比如 Windows 徽标……）这在启动应用程序时非常有用。例如，使用以下键序列 <code>Super + f i r + Enter</code> 可以轻松启动 Firefox Web 浏览器</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/05/Peek-2019-05-23-10-50.gif" alt=""></p><h3 id="消息托盘" tabindex="-1">消息托盘 <a class="header-anchor" href="#消息托盘" aria-label="Permalink to “消息托盘”">​</a></h3><p>在 GNOME 中，消息托盘中提供了通知。这也是日历和世界时钟出现的地方。要使用键盘打开信息托盘，请使用 <code>Super + m</code> 快捷键。要关闭消息托盘，只需再次使用相同的快捷方式。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/05/Peek-2019-05-23-11-01.gif" alt=""></p><h3 id="在-gnome-中管理工作空间" tabindex="-1">在 GNOME 中管理工作空间 <a class="header-anchor" href="#在-gnome-中管理工作空间" aria-label="Permalink to “在 GNOME 中管理工作空间”">​</a></h3><p>GNOME Shell 使用动态工作空间，这意味着它可以根据需要创建更多工作空间。使用 GNOME 提高工作效率的一个好方法是为每个应用程序或每个专用活动使用一个工作区，然后使用键盘在这些工作区之间导航。</p><p>让我们看一个实际的例子。要在当前工作区中打开终端，请按以下键：<code>Super + t e r + Enter</code>。然后，要打开新工作区，请按 <code>Super + PgDn</code>。 打开 Firefox（ <code>Super + f i r + Enter</code>）。 要返回终端（所在的工作空间），请使用 <code>Super + PgUp</code>。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/05/Peek-2019-05-23-12-57.gif" alt=""></p><h3 id="管理应用窗口" tabindex="-1">管理应用窗口 <a class="header-anchor" href="#管理应用窗口" aria-label="Permalink to “管理应用窗口”">​</a></h3><p>使用键盘也可以轻松管理应用程序窗口的大小。最小化、最大化和将应用程序移动到屏幕的左侧或右侧只需几个击键即可完成。使用 <code>Super + ↑</code> 最大化、<code>Super + ↓</code> 最小化、<code>Super + ←</code> 和 <code>Super + →</code> 左右移动窗口。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/05/Peek-2019-05-23-13-06.gif" alt=""></p><h3 id="同一个应用的多个窗口" tabindex="-1">同一个应用的多个窗口 <a class="header-anchor" href="#同一个应用的多个窗口" aria-label="Permalink to “同一个应用的多个窗口”">​</a></h3><p>使用活动概述启动应用程序非常有效。但是，尝试从已经运行的应用程序打开一个新窗口只能将焦点转移到已经打开的窗口。要创建一个新窗口，就不是简单地按 <code>Enter</code> 启动应用程序，请使用 <code>Ctrl + Enter</code>。</p><p>因此，例如，使用应用程序概述启动终端的第二个实例，<code>Super + t e r + (Ctrl + Enter)</code>。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/05/Peek-2019-05-23-13-19.gif" alt=""></p><p>然后你可以使用 <code>Super</code> + ` 在同一个应用程序的窗口之间切换。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/05/Peek-2019-05-23-13-22.gif" alt=""></p>',19)),o("p",null,[e[4]||(e[4]=t("如图所示，当用键盘控制时，GNOME Shell 是一个非常强大的桌面环境。学习使用这些快捷方式并训练你的肌肉记忆以不使用鼠标将为你提供更好的用户体验，并在使用 GNOME 时提高你的工作效率。有关其他有用的快捷方式，请查看 ",-1)),a(r,{href:"https://wiki.gnome.org/Design/OS/KeyboardShortcuts"},{default:n(()=>[...e[3]||(e[3]=[t("GNOME wiki 上的此页面",-1)])]),_:1}),e[5]||(e[5]=t("。",-1))]),o("p",null,[o("em",null,[e[8]||(e[8]=t("图片来自 ",-1)),a(r,{href:"https://unsplash.com/photos/MuTWth_RnEs?utm_source=unsplash&utm_medium=referral&utm_content=creditCopyText"},{default:n(()=>[...e[6]||(e[6]=[t("1AmFcS",-1)])]),_:1}),e[9]||(e[9]=t("，",-1)),a(r,{href:"https://unsplash.com/search/photos/keyboard?utm_source=unsplash&utm_medium=referral&utm_content=creditCopyText"},{default:n(()=>[...e[7]||(e[7]=[t("Unsplash",-1)])]),_:1})])]),e[28]||(e[28]=o("hr",null,null,-1)),o("p",null,[e[11]||(e[11]=t("via: ",-1)),a(r,{href:"https://fedoramagazine.org/5-gnome-keyboard-shortcuts-to-be-more-productive/"},{default:n(()=>[...e[10]||(e[10]=[t("https://fedoramagazine.org/5-gnome-keyboard-shortcuts-to-be-more-productive/",-1)])]),_:1})]),o("p",null,[e[16]||(e[16]=t("作者：",-1)),a(r,{href:"https://fedoramagazine.org/author/cverna/"},{default:n(()=>[...e[12]||(e[12]=[t("Clément Verna",-1)])]),_:1}),e[17]||(e[17]=t(" 选题：",-1)),a(r,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[13]||(e[13]=[t("lujun9972",-1)])]),_:1}),e[18]||(e[18]=t(" 译者：",-1)),a(r,{href:"https://github.com/wxy"},{default:n(()=>[...e[14]||(e[14]=[t("wxy",-1)])]),_:1}),e[19]||(e[19]=t(" 校对：",-1)),a(r,{href:"https://github.com/wxy"},{default:n(()=>[...e[15]||(e[15]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[22]||(e[22]=t("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[20]||(e[20]=[t("LCTT",-1)])]),_:1}),e[23]||(e[23]=t(" 原创编译，",-1)),a(r,{href:"https://linux.cn/"},{default:n(()=>[...e[21]||(e[21]=[t("Linux中国",-1)])]),_:1}),e[24]||(e[24]=t(" 荣誉推出",-1))])])}const k=p(u,[["render",m]]);export{S as __pageData,k as default};
